function x({registerIndicator:m,nulls:N}){m({id:"oa-natr",name:"Normalized Average True Range",category:"Volatility",placement:"pane",inputs:[{key:"length",type:"number",label:"Length",default:14,min:1,max:5e3,step:1,tooltip:"Number of bars used for the ATR calculation"}],plots:[{key:"natr",type:"line",title:"NATR",style:{color:"#ffeb3b",lineWidth:2}}],calc(a,f){const c=a.length,l=Math.max(1,Math.floor(Number(f.length)||14)),b=1-1/l,p=1e-10;let n=0,o=1;const i=new Array(c).fill(NaN);for(let t=0;t<c;t++){const e=a[t],h=t>0&&Number.isFinite(a[t-1].close)?a[t-1].close:e.close,g=e.high-e.low,y=Math.abs(e.high-h),d=Math.abs(e.low-h),u=Math.max(g,Math.max(y,d));let r=NaN;Number.isFinite(u)&&(n=(n*(l-1)+u)/l,o*=b,r=o>p?n/(1-o):n);const s=e.close;Number.isFinite(s)&&s!==0?Number.isFinite(r)&&(i[t]=r/s*100):i[t]=0}return{natr:N(i)}}})}export{x as default};
